1	import { ADMIN, type E2eConfig } from "../config.ts";
2	
3	/**
4	 * The first request after a `docker compose run` (every `manage` call) can find its socket
5	 * closed by the host's port forwarding before Saleor ever sees it - `fetch failed`, "other
6	 * side closed", and nothing in the api log. Only that is retried: an HTTP error or a
7	 * GraphQL error means the request arrived, and is reported as it is.
8	 */
9	const post = async (url: string, init: RequestInit, attempts = 3): Promise<Response> => {
10	  try {
11	    return await fetch(url, init);
12	  } catch (error) {
13	    if (attempts <= 1 || !(error instanceof TypeError)) {
14	      throw error;
15	    }
16	
17	    await new Promise(resolve => setTimeout(resolve, 1000));
18	
19	    return post(url, init, attempts - 1);
20	  }
21	};
22	
23	export const gql = async <T>(
24	  config: E2eConfig,
25	  query: string,
26	  variables: Record<string, unknown> = {},
27	  token?: string,
28	): Promise<T> => {
29	  const response = await post(config.apiUrl, {
30	    method: "POST",
31	    headers: {
32	      "content-type": "application/json",
33	      ...(token ? { authorization: `Bearer ${token}` } : {}),
34	    },
35	    body: JSON.stringify({ query, variables }),
36	  });
37	
38	  if (!response.ok) {
39	    throw new Error(`${config.apiUrl} answered ${response.status}`);
40	  }
41	
42	  const body = (await response.json()) as { data?: T; errors?: { message: string }[] };
43	
44	  if (body.errors?.length) {
45	    throw new Error(body.errors.map(error => error.message).join("; "));
46	  }
47	
48	  if (!body.data) {
49	    throw new Error("response carried neither data nor errors");
50	  }
51	
52	  return body.data;
53	};
54	
55	/**
56	 * Saleor reports mutation failures in the payload rather than as GraphQL errors, so a
57	 * seed step that silently did nothing would otherwise surface much later as a missing row.
58	 */
59	export const assertNoMutationErrors = (name: string, errors: unknown): void => {
60	  if (Array.isArray(errors) && errors.length > 0) {
61	    throw new Error(`${name}: ${JSON.stringify(errors)}`);
62	  }
63	};
64	
65	/**
66	 * `tokenCreate` mints both in one round trip. Seeding drives the API with the access token;
67	 * a stored browser session carries only the refresh one (see `lib/auth.ts`).
68	 */
69	export const signIn = async (
70	  config: E2eConfig,
71	  email: string,
72	  password: string,
73	): Promise<{ token: string; refreshToken: string }> => {
74	  const data = await gql<{
75	    tokenCreate: {
76	      token: string | null;
77	      refreshToken: string | null;
78	      errors: { message: string }[];
79	    };
80	  }>(
81	    config,
82	    `mutation($email: String!, $password: String!) {
83	      tokenCreate(email: $email, password: $password) {
84	        token
85	        refreshToken
86	        errors { field code message }
87	      }
88	    }`,
89	    { email, password },
90	  );
91	
92	  assertNoMutationErrors(`tokenCreate(${email})`, data.tokenCreate.errors);
93	
94	  const { token, refreshToken } = data.tokenCreate;
95	
96	  if (!token || !refreshToken) {
97	    throw new Error(`tokenCreate returned no token for ${email}`);
98	  }
99	
100	  return { token, refreshToken };
101	};
102	
103	export const adminToken = async (config: E2eConfig): Promise<string> =>
104	  (await signIn(config, ADMIN.email, ADMIN.password)).token;
105

