async (page) => {
  const note = page.getByTestId('customer-note');
  const save = page.getByTestId('button-bar-confirm');
  await note.fill('Prefers delivery after 5pm');
  const enabledAfterFill = await save.isEnabled();
  await save.click();
  const toast = page.getByTestId('notification');
  let toastText = null;
  try { await toast.first().waitFor({ timeout: 5000 }); toastText = await toast.first().innerText(); } catch (e) { toastText = 'no [data-test-id=notification]: ' + e.message.split('\n')[0]; }
  const region = await page.getByRole('region', { name: /Notifications/ }).innerText();
  await page.waitForFunction(() => document.querySelector('[data-test-id="button-bar-confirm"]')?.hasAttribute('disabled'), null, { timeout: 5000 }).catch(() => {});
  const disabledAfter = await save.isDisabled();
  const saveHtml = await save.evaluate(e => e.outerHTML.slice(0, 300));
  await page.reload();
  await note.waitFor();
  return { enabledAfterFill, toastText, region, disabledAfter, saveHtml, afterReload: await note.inputValue() };
}

